<?php
require_once __DIR__.'/includes/auth.php'; require_auth(); verify_csrf(); require_once __DIR__.'/includes/groq.php'; $u=current_user(); $id=(int)($_POST['audio_id']??0); $s=$pdo->prepare('SELECT * FROM audio_logs WHERE id=? AND company_id=?');$s->execute([$id,$u['company_id']]);$audio=$s->fetch();if(!$audio){http_response_code(404);exit('Recording not found.');}try{$action=$_POST['action']??'';if($action==='transcribe'){$text=groq_transcribe(__DIR__.'/uploads/'.$audio['filename'],$_POST['language']?:null);$s=$pdo->prepare('UPDATE audio_logs SET transcript=? WHERE id=?');$s->execute([$text,$id]);flash('success','Recording transcribed successfully.');}elseif($action==='suggest'){if(trim((string)$audio['transcript'])==='')throw new RuntimeException('Transcribe the recording first.');$tasks=groq_tasks($audio['transcript']);$s=$pdo->prepare('INSERT INTO ai_task_suggestions(audio_id,company_id,title,description,priority,expected_submit_date) VALUES(?,?,?,?,?,?)');foreach($tasks as $task){$title=trim((string)($task['title']??''));if($title==='')continue;$priority=in_array($task['priority']??'normal',['urgent','important','normal'],true)?$task['priority']:'normal';$date=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($task['due_date']??''))?$task['due_date']:null;$s->execute([$id,$u['company_id'],$title,trim((string)($task['description']??'')),$priority,$date]);}flash('success',count($tasks).' AI task suggestion(s) created for review.');}elseif($action==='accept'){require_manager();$sid=(int)$_POST['suggestion_id'];$s=$pdo->prepare('SELECT s.*,a.project_id FROM ai_task_suggestions s JOIN audio_logs a ON a.id=s.audio_id WHERE s.id=? AND s.company_id=? AND s.status="pending"');$s->execute([$sid,$u['company_id']]);$task=$s->fetch();if(!$task||!$task['project_id'])throw new RuntimeException('Assign the recording to a project before accepting this task.');$s=$pdo->prepare('INSERT INTO tickets(project_id,title,description,expected_submit_date,priority,assigned_to,created_by) VALUES(?,?,?,?,?,?,?)');$s->execute([$task['project_id'],$task['title'],$task['description'],$task['expected_submit_date'],$task['priority'],$task['assigned_to'],$u['id']]);$s=$pdo->prepare('UPDATE ai_task_suggestions SET status="accepted" WHERE id=?');$s->execute([$sid]);flash('success','AI suggestion converted into a ticket.');}}catch(Throwable $e){flash('error',$e->getMessage());}header('Location: audio.php?audio='.$id);exit;
